a <- commandArgs(TRUE); iw <- a[1]; sep <- a[2]
k <- c("dataset","arm","seed","trait")
ci <- read.csv(file.path(iw,"coverage_table.csv")); cs <- read.csv(file.path(sep,"coverage_table.csv"))
m <- merge(ci[,c(k,"model_coverage","model_mean_width","split_coverage")], cs[,c(k,"model_coverage","model_mean_width")], by=k, suffixes=c(".iw",".sep"))
cat("trait-cells:", nrow(m), "\n")
print(aggregate(cbind(model_coverage.iw, model_coverage.sep, split_coverage) ~ dataset, m, function(x) round(c(mean=mean(x), min=min(x), max=max(x)),3)))
cat("width ratio sep/iw by dataset:\n"); print(aggregate(I(model_mean_width.sep/model_mean_width.iw) ~ dataset, m, function(x) round(range(x),3)))
cat("model below split: iw", sum(m$model_coverage.iw < m$split_coverage), " sep", sum(m$model_coverage.sep < m$split_coverage), "of", nrow(m), "\n")
k2 <- c("dataset","arm","seed","response","predictor")
si <- read.csv(file.path(iw,"slope_table.csv")); ss <- read.csv(file.path(sep,"slope_table.csv"))
s <- merge(si[,c(k2,"ref_slope","mi_slope","rel_diff","diff_ref_se","within_5pct")], ss[,c(k2,"mi_slope","rel_diff","diff_ref_se","within_5pct")], by=k2, suffixes=c(".iw",".sep"))
s$cell <- paste(substr(s$dataset,1,4), substr(s$arm,1,4), s$seed %% 100)
print(s[order(s$dataset,s$response,s$predictor,s$arm,s$seed), c("cell","response","predictor","ref_slope","mi_slope.iw","mi_slope.sep","diff_ref_se.iw","diff_ref_se.sep")], digits=3, row.names=FALSE)
cat("within 5%: iw", sum(s$within_5pct.iw), " sep", sum(s$within_5pct.sep), "of", nrow(s), "\n")
cat("max |diff in ref SEs|: iw", max(abs(s$diff_ref_se.iw)), " sep", max(abs(s$diff_ref_se.sep)), "\n")
